module HintCounter (\n    // Clock and control\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    \n    // Problem size (1-8 problems, 1-4 hints)\n    input wire [7:0] n,  // Number of problems\n    input wire [7:0] m,  // Number of hints\n    \n    // Hints (4 hints max, packed into individual ports)\n    // Each hint: l (left bound, 1-indexed), r (right bound, 1-indexed), type (0=same, 1=different)\n    input wire [7:0] l_0, l_1, l_2, l_3,\n    input wire [7:0] r_0, r_1, r_2, r_3,\n    input wire type_0, type_1, type_2, type_3,\n    \n    // Output: count of valid sequences modulo 10^9+7\n    output reg [31:0] result,\n    output reg done\n);\n\n// State definitions\nlocalparam [1:0] IDLE = 2'b00;\nlocalparam [1:0] COMPUTE = 2'b01;\nlocalparam [1:0] DONE = 2'b10;\n\n// Registers for iteration\nreg [1:0] state;\nreg [7:0] seq;          // Current sequence (0 to 2^n-1)\nreg [2:0] hint_idx;     // Current hint index (0 to m-1)\nreg [31:0] count;       // Valid sequence counter\nreg [7:0] max_seq;      // Maximum sequence value (2^n - 1)\nreg [7:0] cycle_count;  // Cycle counter for timeout prevention\nlocalparam [7:0] MAX_CYCLES = 8'd250;  // Max iterations (256 sequences * 4 hints)\n\n// Helper: Current hint data\nwire [7:0] current_l;\nwire [7:0] current_r;\nwire current_type;\n\nassign current_l = (hint_idx == 3'd0) ? l_0 :\n                   (hint_idx == 3'd1) ? l_1 :\n                   (hint_idx == 3'd2) ? l_2 : l_3;\nassign current_r = (hint_idx == 3'd0) ? r_0 :\n                   (hint_idx == 3'd1) ? r_1 :\n                   (hint_idx == 3'd2) ? r_2 : r_3;\nassign current_type = (hint_idx == 3'd0) ? type_0 :\n                      (hint_idx == 3'd1) ? type_1 :\n                      (hint_idx == 3'd2) ? type_2 : type_3;\n\n// Mask generation: creates bit mask for range [l-1:r-1]\nwire [8:0] full_mask = (9'd1 << current_r) - (9'd1 << (current_l - 1));\nwire [7:0] mask = full_mask[7:0] & ((8'd1 << n) - 8'd1);  // Mask to n bits\n\n// Extract bits from current sequence\nwire [7:0] masked_bits = seq & mask;\nwire bits_all_0 = (masked_bits == 8'b0);\nwire bits_all_1 = (masked_bits == mask);\n\n// Hint validation logic\nwire hint_pass = current_type ? \n                 ~(bits_all_0 | bits_all_1) :  // different: not all same\n                 (bits_all_0 | bits_all_1);    // same: all same\n\n// Main state machine\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        seq <= 8'd0;\n        hint_idx <= 3'd0;\n        count <= 32'd0;\n        result <= 32'd0;\n        done <= 1'b0;\n        max_seq <= 8'd0;\n        cycle_count <= 8'd0;\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                cycle_count <= 8'd0;\n                if (start) begin\n                    state <= COMPUTE;\n                    seq <= 8'd0;\n                    hint_idx <= 3'd0;\n                    count <= 32'd0;\n                    max_seq <= (8'd1 << n) - 8'd1;\n                end\n            end\n            \n            COMPUTE: begin\n                cycle_count <= cycle_count + 8'd1;\n                \n                if (seq > max_seq || cycle_count >= MAX_CYCLES) begin\n                    // All sequences processed or timeout\n                    state <= DONE;\n                    result <= count % 32'd1000000007;\n                    done <= 1'b1;\n                end else if (hint_idx >= m) begin\n                    // All hints passed for current sequence\n                    count <= count + 32'd1;\n                    seq <= seq + 8'd1;\n                    hint_idx <= 3'd0;\n                end else if (hint_pass) begin\n                    // Current hint passed, check next\n                    hint_idx <= hint_idx + 3'd1;\n                end else begin\n                    // Current hint failed, skip to next sequence\n                    seq <= seq + 8'd1;\n                    hint_idx <= 3'd0;\n                end\n            end\n            \n            DONE: begin\n                // Maintain done signal until reset\n            end\n            \n            default: begin\n                state <= IDLE;\n            end\n        endcase\n    end\nend\n\nendmodule